import { ref } from 'vue'

const UnnecessaryRendersDemo = {
  setup() {
    const count = ref(0)
    const unrelatedValue = ref(0)

    const increment = () => {
      count.value++
    }

    const updateUnrelated = () => {
      unrelatedValue.value += 5
    }

    return {
      count,
      unrelatedValue,
      increment,
      updateUnrelated
    }
  },
  template: `
    <div>
      <p>Count: {{ count }}</p>
      <button @click="increment">Increment</button>
